CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE IF NOT EXISTS users (id VARCHAR(64) PRIMARY KEY, telegram_id BIGINT UNIQUE, full_name VARCHAR(120) NOT NULL, role VARCHAR(32) NOT NULL CHECK (role IN ('intern','buddy','manager')), job_title VARCHAR(80) NOT NULL, team VARCHAR(80) NOT NULL, cluster VARCHAR(80) NOT NULL, mentor_id VARCHAR(64) REFERENCES users(id), manager_id VARCHAR(64) REFERENCES users(id), xp INTEGER NOT NULL DEFAULT 0, level INTEGER NOT NULL DEFAULT 1, streak_days INTEGER NOT NULL DEFAULT 1, last_pulse_date DATE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS roadmap_nodes (id VARCHAR(64) PRIMARY KEY, period VARCHAR(32) NOT NULL, title VARCHAR(160) NOT NULL, description TEXT NOT NULL, node_type VARCHAR(32) NOT NULL, xp_reward INTEGER NOT NULL DEFAULT 50, order_index INTEGER NOT NULL, target_role VARCHAR(32) NOT NULL DEFAULT 'intern', verification_config JSONB NOT NULL DEFAULT '{}'::jsonb, depends_on_node_id VARCHAR(64) REFERENCES roadmap_nodes(id));
CREATE TABLE IF NOT EXISTS user_node_progress (id SERIAL PRIMARY KEY, user_id VARCHAR(64) NOT NULL REFERENCES users(id) ON DELETE CASCADE, node_id VARCHAR(64) NOT NULL REFERENCES roadmap_nodes(id) ON DELETE CASCADE, status VARCHAR(32) NOT NULL, verified_artifact TEXT, verification_feedback TEXT, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(user_id,node_id));
CREATE TABLE IF NOT EXISTS service_requests (id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL REFERENCES users(id) ON DELETE CASCADE, tool_name VARCHAR(64) NOT NULL, idempotency_key VARCHAR(128) NOT NULL UNIQUE, payload JSONB NOT NULL, status VARCHAR(32) NOT NULL, external_ticket_id VARCHAR(64), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS calendar_events (id VARCHAR(64) PRIMARY KEY, user_id VARCHAR(64) NOT NULL REFERENCES users(id) ON DELETE CASCADE, participant_id VARCHAR(64) REFERENCES users(id), title VARCHAR(160) NOT NULL, event_type VARCHAR(32) NOT NULL, starts_at TIMESTAMPTZ NOT NULL, duration_min INTEGER NOT NULL DEFAULT 30, agenda TEXT, auto_summary TEXT);
CREATE TABLE IF NOT EXISTS daily_pulses (id SERIAL PRIMARY KEY, user_id VARCHAR(64) NOT NULL REFERENCES users(id) ON DELETE CASCADE, pulse_date DATE NOT NULL DEFAULT CURRENT_DATE, mood_score INTEGER NOT NULL CHECK (mood_score BETWEEN 1 AND 5), blocker_tags TEXT[] NOT NULL DEFAULT '{}', comment TEXT, xp_awarded INTEGER NOT NULL DEFAULT 15, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(user_id,pulse_date));
CREATE TABLE IF NOT EXISTS knowledge_chunks (id VARCHAR(64) PRIMARY KEY, doc_title VARCHAR(200) NOT NULL, source_url VARCHAR(300) NOT NULL, source_scope VARCHAR(32) NOT NULL, cluster VARCHAR(80), allowed_roles TEXT[] NOT NULL DEFAULT '{intern,buddy,manager}', topic_key VARCHAR(80) NOT NULL, version_date DATE NOT NULL, content TEXT NOT NULL, embedding vector(384));
CREATE TABLE IF NOT EXISTS clickstream_events (id BIGSERIAL PRIMARY KEY, user_id VARCHAR(64) NOT NULL, role VARCHAR(32) NOT NULL, event_name VARCHAR(80) NOT NULL, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_progress_user ON user_node_progress(user_id);
CREATE INDEX IF NOT EXISTS idx_calendar_user_date ON calendar_events(user_id, starts_at);
CREATE INDEX IF NOT EXISTS idx_knowledge_scope_cluster ON knowledge_chunks(source_scope, cluster, topic_key);
CREATE INDEX IF NOT EXISTS idx_clickstream_name_time ON clickstream_events(event_name, created_at);
CREATE INDEX IF NOT EXISTS idx_knowledge_embedding_hnsw ON knowledge_chunks USING hnsw (embedding vector_cosine_ops);

